"""一次性离线核验 v62；不构建、不重跑 LP。"""
import collections, copy, datetime, gzip, hashlib, json, math, re, statistics, subprocess, sys, zipfile
from pathlib import Path
sys.dont_write_bytecode = True
ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "knowledge/experiments/data/2026-10-12-halpern-ipm"
PLAN_SHA = "72bfab365ee388a4db2357f111531558772cf5ac07e28e1b0e9fbd5c0cf96c9b"
FIELDS = ("ipm_extended_krylov_attempts", "ipm_extended_krylov_successes",
          "ipm_homogeneous_scalar_checks", "ipm_homogeneous_scalar_rejections")
SCALAR_FIELDS = FIELDS[2:]
COMPAT = ("compatibility-development", "compatibility-probe")
STAGES = (*COMPAT, "development", "probe", "netlib", "highs")
ALLOWED = {"optimal": (0, "resolved"), "empty": (0, "resolved"), "infeasible": (0, "resolved"),
    "unbounded": (0, "resolved"), "verification_failed": (3, "verification_failed"),
    "time_limit": (4, "incomplete"), "iteration_limit": (4, "incomplete"), "numerical_error": (4, "incomplete")}

def require(condition, message):
    if not condition:
        raise AssertionError(message)

def strict(text):
    def pairs(values):
        result = {}
        for key, value in values:
            require(key not in result, "JSON 重复键")
            result[key] = value
        return result
    def number(text):
        value = float(text)
        require(math.isfinite(value), "JSON 非有限浮点")
        return value
    def invalid(text):
        raise ValueError("JSON 非有限常量：" + text)
    return json.loads(text, object_pairs_hook=pairs, parse_float=number, parse_constant=invalid)

def read(path):
    return strict(Path(path).read_text(encoding="utf-8"))

def sha(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

def finite(value):
    return type(value) in (int, float) and math.isfinite(value)

def same(a, b):
    if type(a) is bool or type(b) is bool:
        return type(a) is type(b) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[key], b[key]) for key in a)
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b

def flags(arguments):
    require(len(arguments) % 2 == 0, "参数必须成对")
    result = dict(zip(arguments[::2], arguments[1::2]))
    require(len(result) * 2 == len(arguments) and all(key.startswith("--") for key in result), "重复或非法参数")
    return result

def valid_counts(report, version, backend, mode):
    present = [key in report for key in FIELDS]
    if version == 57 and not any(present):
        return True
    if not all(present):
        return False
    values = [report[key] for key in FIELDS]
    if backend != "ipm":
        return all(value is None for value in values)
    if not all(type(value) is int and 0 <= value <= 9223372036854775807 for value in values):
        return False
    attempts, successes, checks, rejections = values
    return successes <= attempts and rejections <= checks and (
        mode == "homogeneous_extended" or all(value == 0 for value in values))

def valid_process(row):
    report = row.get("report")
    if row.get("error") is not None or not isinstance(report, dict) or type(row.get("returncode")) is not int:
        return False
    if type(report.get("schema_version")) is not int or report["schema_version"] != 1:
        return False
    status = report.get("status")
    if not isinstance(status, str) or status not in ALLOWED or row.get("status") != status:
        return False
    if (row["returncode"], row.get("classification")) != ALLOWED[status]:
        return False
    times = report.get("timings")
    if not isinstance(times, dict) or not all(finite(times.get(key)) and times[key] >= 0 for key in ("read_seconds", "solve_seconds", "verification_seconds", "total_seconds")):
        return False
    return finite(row.get("elapsed_wall_seconds")) and row["elapsed_wall_seconds"] > 0 and finite(row.get("numerical_seconds")) and row["numerical_seconds"] >= 0

def limited(row):
    return row.get("error") == "wall_timeout" or (row.get("report") or {}).get("status") == "time_limit" or (finite(row.get("elapsed_wall_seconds")) and row["elapsed_wall_seconds"] > 35) or (finite(row.get("numerical_seconds")) and row["numerical_seconds"] > 5)

def trajectory(a, b):
    reports = copy.deepcopy([a.get("report"), b.get("report")])
    for report in reports:
        if isinstance(report, dict):
            for key in ("timings", "backend_version", *FIELDS):
                report.pop(key, None)
    equal = same(*reports) and a.get("returncode") == b.get("returncode") and a.get("error") == b.get("error")
    valid, budget = valid_process(a) and valid_process(b), limited(a) or limited(b)
    return {"equal": equal, "valid_processes": valid, "budget_limited": budget,
        "category": "invalid_process" if not valid else "budget_limited" if budget else "equal" if equal else "different"}

def self_check():
    cases = [({}, 57, "ipm", "homogeneous_repair", True), ({}, 62, "ipm", "homogeneous_extended", False)]
    for values, mode, good in (
        ((0, 0, 0, 0), "homogeneous_repair", True),
        ((1, 1, 3, 2), "homogeneous_extended", True),
        ((1, 0, 2, 2), "homogeneous_extended", True),
        ((0, 0, 0, 0), "homogeneous_extended", True),
        (((1 << 63) - 1,) * 4, "homogeneous_extended", True),
        ((1, 2, 0, 0), "homogeneous_extended", False),
        ((0, 0, 1, 2), "homogeneous_extended", False)):
        cases.append((dict(zip(FIELDS, values)), 62, "ipm", mode, good))
    for field in FIELDS:
        invalid_mode = dict.fromkeys(FIELDS, 0)
        invalid_mode[field] = 1
        cases.append((invalid_mode, 62, "ipm", "homogeneous_repair", False))
        for value in (True, False, -1, 1.0, 1 << 63):
            invalid = dict.fromkeys(FIELDS, 0)
            invalid[field] = value
            cases.append((invalid, 62, "ipm", "homogeneous_extended", False))
        partial = dict.fromkeys(FIELDS, 0)
        del partial[field]
        cases.append((partial, 62, "ipm", "homogeneous_extended", False))
    cases += [(dict.fromkeys(FIELDS, None), 62, "highs", "homogeneous_extended", True),
              (dict.fromkeys(FIELDS, 0), 62, "highs", "homogeneous_extended", False),
              ({FIELDS[0]: 0}, 57, "ipm", "homogeneous_repair", False)]
    for report, version, backend, mode, good in cases:
        require(valid_counts(report, version, backend, mode) is good, "计数反例")
    status_cases = 0
    for status in ALLOWED:
        for field in FIELDS:
            invalid = {"status": status, **dict.fromkeys(FIELDS, 0)}
            invalid[field] = True
            require(not valid_counts(invalid, 62, "ipm", "homogeneous_extended"), "所有状态均拒绝非法计数")
            status_cases += 1
    row = {"error": None, "classification": "incomplete", "status": "numerical_error", "returncode": 4,
        "report": {"schema_version": 1, "status": "numerical_error", "backend_version": "ipm-cpu-0.47.0", "timings": {"read_seconds": 0, "solve_seconds": 1, "verification_seconds": 0, "total_seconds": 1}}, "numerical_seconds": 1, "elapsed_wall_seconds": 2}
    modern = copy.deepcopy(row)
    modern["report"].update(backend_version="ipm-cpu-0.50.0", **dict.fromkeys(FIELDS, 0))
    require(trajectory(row, modern)["category"] == "equal", "兼容排除字段")
    budget = copy.deepcopy(row)
    budget["status"] = budget["report"]["status"] = "time_limit"
    require(trajectory(row, budget)["category"] == "budget_limited", "合法预算分叉")
    invalids = []
    for status in ("bogus", None, True):
        bad = copy.deepcopy(row)
        bad["status"] = bad["report"]["status"] = status
        invalids.append(bad)
    for key, value in (("returncode", False), ("returncode", -1073741819), ("error", "wall_timeout"), ("numerical_seconds", None)):
        bad = copy.deepcopy(row)
        bad[key] = value
        invalids.append(bad)
    for bad in invalids:
        require(trajectory(bad, budget)["category"] == "invalid_process", "invalid 必须优先于预算")
    require(not same({"x": True}, {"x": 1}), "布尔不得冒充整数")
    try:
        strict('{"x":1,"x":2}')
    except AssertionError:
        pass
    else:
        raise AssertionError("重复 JSON 键未拒绝")
    return {"passed": True, "count_cases": len(cases), "all_status_count_cases": status_cases, "trajectory_cases": 2 + len(invalids), "invalid_budget_counterexamples": len(invalids), "json_and_type_cases": 2, "lp_runs": 0}

